"""One Russian page for entirely independent official Handoff Debt trials."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
def add_handoff_debt(w):
    j=json.loads((ROOT/"results.json").read_text(encoding="utf-8"))
    all_=j["conditions"]["all"];a=all_["arms"]
    w.page("Независимый набор · Handoff Debt", "Когда передавать полную историю",
           "На 6 120 опубликованных запусках проверили правило: передавать весь журнал после правки, последовавшей за неудачной проверкой. В остальных состояниях передавать структурированную записку.")
    w.p("Использованы первые попытки Qwen3.6-27B, Gemma 4 31B и Devstral Small 2 24B из публичного набора авторов. Для 510 точек передачи на 75 задачах SWE-bench Verified доступны все четыре способа и три получателя. Правило зафиксировали до открытия исходов отдельных прогонов. Для каждой точки и модели подставили наблюдённый результат выбранного способа.")
    rows=[]
    for name,k in [("Только рабочее дерево","repo_only"),("Свободная записка","summary_notes"),("Структурированная записка","structured_notes"),("Полный журнал","raw_trace"),("Журнал только после ошибки и правки","policy")]:
        d=a[k]
        rows.append((name,d["official_solved"],d["official_unknown"],str(round(d["agent_events"]["mean"],1)).replace(".",","),
                     str(round(d["prompt_tokens"]["mean"]/1e6,2)).replace(".",",")))
    w.tbl(["Вид передачи","Решено / 1 530","Нет полного исхода","Событий, среднее","Вход, млн токенов"],rows,[6.0,2.7,3.0,2.7,2.7],True)
    w.p("На 255 из 1 530 сочетаний правило выбрало полный журнал. Смена условия дала 13 выигрышей и 10 потерь против постоянных структурированных записок. Разница +0,20 п.п., 95% интервал по 75 исходным задачам от −0,53 до +0,89 п.п., описательный точный p = 0,678. Среди 1 469 пар с двумя известными исходами разница составила +0,20 п.п.")
    w.p("Передача по правилу потребовала в среднем на 52 058 входных токенов больше, чем структурированная записка, на 1 521 паре с известной стоимостью обеих форм. Число событий агента сократилось в среднем на 3,90. Постоянная передача полного журнала дала ещё 25 решённых случаев. Одна только стадия предшествующей работы недостаточна для вывода о преимуществе выбранной политики.")
    w.p("Из 6 120 строк у 238 отсутствует явная официальная отметка resolved. В таблице засчитаны только подтверждённые решения. Четыре положительных исхода расходятся с полем validation_passed релиза. По этому второму полю правило всё равно даёт перевес в три решения. С предыдущим локальным пилотом совпадает репозиторий Requests, общих целевых задач и PR нет.","Caption")
    w.source("Handoff Debt · статья и экспериментальный протокол","https://arxiv.org/abs/2606.02875")
    w.source("Handoff Debt · выпущенные авторами прогоны на фиксированной версии",
             "https://huggingface.co/datasets/kc-academy/handoff-debt/tree/79244eedc9d58349da0fcf1a2e05916e0ac5af00")
    w.page("Handoff Debt · отложенные попытки", "Можно ли отдавать полный журнал выборочно?",
           "Выбор между запиской и полной историей по этапу работы дал 38 решений из 80. Постоянная передача полного журнала тоже дала 38. Выборочная передача потребовала в среднем на 27% меньше входных токенов.")
    w.p("В отдельной проверке использованы ещё 320 опубликованных исполнений. Взяли 40 точек прерывания и две новые попытки на каждую для пары Qwen→Qwen. Исключили все 22 тестовые задачи из обучения. На 53 других задачах и 1 056 сопоставимых состояниях r01 оценили вероятность решения для каждой формы. Назначения и параметры зафиксировали до открытия исходов r02/r03.")
    w.tbl(["Как выбрать формат", "Полный журнал", "Решено / 80", "Средний вход, токенов"],
          [("Всегда полный журнал","80 / 80","38","1 735 528 (n=79)"),
           ("Всегда свободная записка","0 / 80","36","1 103 848 (n=80)"),
           ("Всегда структурированная записка","0 / 80","35","1 217 752 (n=80)"),
           ("Модель + этап, сглаживание 16","30 / 80","38","1 259 870 (n=80)"),
           ("Иерархия моделей и этапа, сглаживание 20","50 / 80","38","1 502 574 (n=80)")],
          [7.0,3.0,2.5,4.6],True)
    w.p("Первое правило с 16 псевдонаблюдениями выбрало полный журнал после первой проверки и свободную записку в остальных состояниях. Два выигрыша к постоянной свободной записке пришлись на ту же точку pydata/xarray №3993 в двух повторах; потерь нет, p = 0,50. Относительно полного журнала у обеих политик по три выигрыша и три потери. Разница 0 п.п., 95% интервал по задачам от −3,49 до +3,75 п.п. В 78 парах с явным статусом обеих форм разница также нулевая.")
    w.p("Относительно полного журнала первая политика использовала на 473 538 входных токенов меньше на 79 парах. По отношению к свободной записке она потребовала на 156 022 токена больше (+14,1%), к структурированной — на 42 118 больше (+3,5%). У второй политики соответствующие разницы −227 762, +398 726 и +284 822. Диагностические интервалы экономии относительно полного журнала в таблицах архива.")
    w.p("Входные токены суммируются по работе преемника. Авторы исключили расходы генерации исходных записок, отдельная проверка всех 6 665 строк таблицы handoffs подтвердила отсутствие полей затрат на генерацию. Одна модель-получатель и 40 отобранных точек ограничивают обобщение. Для сравнения стоимости при заданном качестве нужна независимая серия с заранее выбранной границей допустимого ухудшения.","Caption")

